const categories = [ "Restauration", "Animation", "Grande Distribution", "Informatique","Construction","Intérim (Logistique Pro Service)","Bénévolat"];

export default function Experiences() {
const [activeCategory, setActiveCategory] = useState("Informatique");

  const filteredData =
    activeCategory === "I"
      ? experiencesData
      : experiencesData.filter(exp => exp.category === activeCategory);

  return (
    <div className="experiences">
      <div className="card-tabs-nav flat">
        {categories.map(cat => (
          <button
            key={cat}
            onClick={() => setActiveCategory(cat)}
            className={`card-tab-btn ${activeCategory === cat ? 'active' : ''}`}
          >
            {cat}
          </button>
        ))}
      </div>

      <ul className="experience-list card-deck-refresh" key={activeCategory}>
        {filteredData.map(({ title, start, end, details, logo }, index) => (
          <ScrollReveal
            as="li"
            key={index}
            className="experience-card"
            direction="up"
            delay={(index % 6) * 90}
          >
            <div className="card-inner">
              <div className="card-front">
                {logo && (
                  <img src={logo} alt={`Logo ${title}`} className="card-logo" />
                )}
                <h3>{title}</h3>
                <time dateTime={start}>
                  {new Date(start).toLocaleDateString('fr-FR')}
                </time>
                {" – "}
                {end.toLowerCase() === "présent" ? "présent" : (
                  <time dateTime={end}>
                    {new Date(end).toLocaleDateString('fr-FR')}
                  </time>
                )}
              </div>
              <div className="card-back">
                <ul className="details">
                  {details.map((detail, i) => <li key={i}>{detail}</li>)}
                </ul>
              </div>
            </div>
          </ScrollReveal>
        ))}
      </ul>
    </div>
  );
}